<script setup>
import {previewMode} from "../preview/mode"
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import Icon from '../Icon.vue'
import {request} from './client'
const props=defineProps({member:Object,rooms:Array})
const manager=computed(()=>props.member.role!=='Student'),rows=ref([]),error=ref(''),message=ref(''),busy=ref(false),filter=ref('All'),page=ref(0),editor=ref(null),selected=ref(null),attempt=ref(null),answers=ref([]),reviews=ref([]),reviewed=ref(false),premium=ref(false),topic=ref(''),aiRoom=ref(''),aiOpen=ref(false),count=ref(5),now=ref(Date.now()),serverOffset=ref(0)
const tick=setInterval(()=>now.value=Date.now(),1000);onBeforeUnmount(()=>clearInterval(tick))
const seconds=computed(()=>attempt.value?Math.max(0,Math.floor((Date.parse(attempt.value.deadline.replace(' ','T'))-now.value-serverOffset.value)/1000)):0)
const clock=computed(()=>`${String(Math.floor(seconds.value/60)).padStart(2,'0')}:${String(seconds.value%60).padStart(2,'0')}`)
const visible=computed(()=>rows.value.filter(p=>filter.value==='All'||p.source===filter.value))
watch(editor,()=>reviewed.value=false,{deep:true})
function question(){return {kind:'MCQ',prompt:'',options:['','','',''],answer:0,marks:1}}
function create(){selected.value=null;editor.value={classroom:props.rooms[0]?.name||'',title:'',description:'',duration_minutes:60,questions:[question()],opens_at:'',closes_at:'',material:'',allow_upload:false};reviewed.value=false}
async function run(fn){error.value='';message.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){rows.value=await request('papers','listing',{page:page.value});if(manager.value)premium.value=(await request('owner_pricing','entitlements'))['AI Papers']}
async function save(){await run(async()=>{const result=await request('papers','draft',{data:editor.value});editor.value.name=result.name;message.value='Draft saved. Review all questions and correct answers before publishing.';await load()})}
async function publish(){await run(async()=>{await request('papers','publish',{name:editor.value.name,reviewed:reviewed.value});editor.value=null;await load();message.value='Paper published to this classroom.'})}
async function open(p){await run(async()=>{selected.value=await request('papers','detail',{name:p.name});attempt.value=null;reviews.value=await request('papers','submissions',{paper:p.name});if(manager.value&&p.status==='Draft'){editor.value={...selected.value};reviewed.value=false}else editor.value=null})}
async function begin(){await run(async()=>{attempt.value=await request('papers','start',{name:selected.value.name});serverOffset.value=Date.parse(attempt.value.server_time.replace(' ','T'))-Date.now();answers.value=attempt.value.questions.map(q=>q.kind==='Written'?'':null)})}
async function submit(){await run(async()=>{const r=await request('papers','submit',{attempt:attempt.value.attempt,answers:answers.value});attempt.value=null;reviews.value=await request('papers','submissions',{paper:selected.value.name});message.value=r.status==='Graded'?`Submitted. Score: ${r.score} / ${selected.value.max_marks}`:'Submitted for teacher marking.'})}
async function mark(a){await run(async()=>{await request('papers','mark',{attempt:a.name,score:a.score,feedback:a.feedback||''});message.value='Marks and feedback saved.';reviews.value=await request('papers','submissions',{paper:selected.value.name})})}
async function generate(){await run(async()=>{const r=await request('papers','generate',{classroom:aiRoom.value,topic:topic.value,count:count.value});editor.value=await request('papers','detail',{name:r.name});aiOpen.value=false;reviewed.value=false;await load();message.value='AI draft ready. Check accuracy and suitability before publishing.'})}
async function upload(event){await run(async()=>{const file=event.target.files[0];if(!file)return;if(previewMode)throw Error('File uploads require the connected Frappe server. No file was sent.');const body=new FormData();body.append('file',file);body.append('attempt',attempt.value.attempt);const r=await fetch('/api/method/institute_lms.papers.upload_answer',{method:'POST',credentials:'same-origin',headers:{'X-Frappe-CSRF-Token':window.csrf_token||''},body});if(!r.ok)throw Error('Answer upload failed. Use a PDF up to 10 MB within the time limit.');message.value='PDF attached. Submit your attempt to send it for marking.'})}
onMounted(()=>run(load))
</script>
<template><section class="paper-space"><div class="page-heading"><div><span class="eyebrow">A LITTLE PRACTICE. A LITTLE PROGRESS.</span><h1>Papers</h1><p>{{manager?'One place for manual papers, AI drafts and thoughtful feedback.':'Your classroom papers, timed practice and teacher feedback.'}}</p></div><div v-if="manager" class="inline"><button class="button subtle" @click="aiOpen=!aiOpen"><Icon name="Sparkles" :size="16"/>AI Papers · Premium</button><button class="button primary" @click="create">Create paper</button></div></div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status" class="form-note">{{message}}</p>
<form v-if="aiOpen" class="panel paper-panel" @submit.prevent="generate"><h2>A starting point for your next paper.</h2><p>AI creates a draft. You check every question, answer and mark before students can see it. Don’t include student details.</p><p v-if="!premium" class="badge violet">Premium access is not active. Contact your administrator for assigned pricing.</p><label>Classroom<select v-model="aiRoom" required><option disabled value="">Select a classroom</option><option v-for="r in rooms" :value="r.name">{{r.title}}</option></select></label><label>Topic, level and language<textarea v-model="topic" minlength="5" maxlength="2000" required placeholder="For example: Grade 8 fractions, English, medium difficulty"></textarea></label><label>Questions<input v-model.number="count" type="number" min="1" max="20" required></label><button class="button primary" :disabled="busy||!premium">{{busy?'Preparing your draft…':'Generate draft'}}</button></form>
<form v-if="editor" class="panel paper-panel" @submit.prevent="save"><div class="section-heading"><h2>{{editor.name?'Review your draft':'Create a paper'}}</h2><button type="button" class="text-button" @click="editor=null">Close editor</button></div><div class="paper-fields"><label>Title<input v-model="editor.title" maxlength="120" required></label><label>Classroom<select v-model="editor.classroom" required :disabled="!!editor.name"><option v-for="r in rooms" :value="r.name">{{r.title}}</option></select></label><label>Duration in minutes<input v-model.number="editor.duration_minutes" type="number" min="1" max="360" required></label><label>Opens at (site time)<input v-model="editor.opens_at" type="datetime-local"></label><label>Closes at (site time)<input v-model="editor.closes_at" type="datetime-local"></label><label>Instructions<textarea v-model="editor.description" maxlength="2000"></textarea></label></div><label>Existing classroom document ID (optional)<input v-model="editor.material" placeholder="Attach an uploaded paper PDF from classroom materials"></label><label class="paper-check"><input v-model="editor.allow_upload" type="checkbox">Allow students to attach an answer PDF (up to 10 MB)</label>
<article v-for="(q,i) in editor.questions" :key="i" class="paper-question"><div class="section-heading"><strong>Question {{i+1}}</strong><button v-if="editor.questions.length>1" type="button" class="text-button" @click="editor.questions.splice(i,1)">Remove</button></div><div class="paper-fields"><label>Question type<select v-model="q.kind"><option>MCQ</option><option>True/False</option><option>Written</option></select></label><label>Marks<input v-model.number="q.marks" type="number" min="1" max="100" required></label></div><label>Question<textarea v-model="q.prompt" maxlength="3000" required></textarea></label><template v-if="q.kind==='MCQ'"><label v-for="(_,j) in q.options">Option {{String.fromCharCode(65+j)}}<input v-model="q.options[j]" maxlength="500" required></label></template><label v-if="q.kind!=='Written'">Correct answer<select v-model.number="q.answer"><option v-for="(value,j) in q.kind==='True/False'?['True','False']:q.options" :value="j">{{q.kind==='True/False'?value:String.fromCharCode(65+j)+' · '+value}}</option></select></label></article><button type="button" class="button subtle" :disabled="editor.questions.length>=100" @click="editor.questions.push(question())">Add question</button><div class="paper-actions"><button class="button primary" :disabled="busy">Save draft</button><label v-if="editor.name" class="paper-check"><input v-model="reviewed" type="checkbox">I have reviewed the saved paper and answer key.</label><button v-if="editor.name" type="button" class="button primary" :disabled="busy||!reviewed" @click="publish">Publish saved draft</button></div><p>Save your changes before publishing. Published questions cannot be edited after students begin.</p></form>
<template v-else><div class="paper-tabs"><button v-for="f in ['All','Manual','AI']" :class="{active:filter===f}" @click="filter=f">{{f==='AI'?'AI Papers':f==='Manual'?'Manual Papers':f}}</button></div><div v-if="!selected" class="paper-grid"><article v-for="p in visible" class="panel paper-panel"><span class="badge violet">{{p.source==='AI'?'✦ AI · Reviewed before release':'Manual'}} · {{p.status}}</span><h2>{{p.title}}</h2><p>{{p.duration_minutes}} minutes · {{p.max_marks}} marks</p><p>{{rooms.find(r=>r.name===p.classroom)?.title}}</p><button class="button subtle" @click="open(p)">Open paper →</button></article><div v-if="!visible.length" class="panel paper-panel paper-empty"><Icon name="NotebookPen" :size="35"/><h2>{{manager?'Your next paper starts here.':'A little room for what’s next.'}}</h2><p>{{manager?'Create a manual paper or start with a premium AI draft.':'Published papers from your classes will appear here.'}}</p></div></div>
<section v-else class="panel paper-panel"><button class="text-button" @click="selected=null;attempt=null">← All papers</button><h2>{{selected.title}}</h2><p>{{selected.description}}</p><p>{{selected.duration_minutes}} minutes · {{selected.max_marks}} marks</p><a v-if="selected.material" :href="'/api/method/institute_lms.materials.content?material='+encodeURIComponent(selected.material)+'&action=view'" target="_blank" rel="noopener">View attached classroom paper</a><button v-if="!manager&&!attempt&&!reviews.length" class="button primary" :disabled="busy" @click="begin">Start timed attempt</button><template v-if="attempt"><div class="paper-clock" role="timer">{{clock}} remaining</div><fieldset v-for="(q,i) in attempt.questions" class="paper-question" :disabled="seconds===0"><legend>{{i+1}}. {{q.prompt}} · {{q.marks}} marks</legend><textarea v-if="q.kind==='Written'" v-model="answers[i]" maxlength="10000" aria-label="Written answer"></textarea><label v-else v-for="(o,j) in q.options" class="paper-check"><input v-model="answers[i]" type="radio" :name="'answer-'+i" :value="j">{{o}}</label></fieldset><label v-if="selected.allow_upload">Answer PDF<input type="file" accept="application/pdf" @change="upload" :disabled="!seconds||busy"></label><button class="button primary" :disabled="busy||!seconds" @click="submit">Submit answers</button><p v-if="!seconds" role="alert">Time has ended. Contact your teacher if you had a technical problem.</p></template><template v-if="manager"><article v-for="(q,i) in selected.questions" class="paper-question"><strong>{{i+1}}. {{q.prompt}}</strong><p>{{q.kind==='Written'?'Teacher-marked answer':q.options[q.answer]}} · {{q.marks}} marks</p></article><button class="button subtle" @click="run(async()=>{await request('papers','archive',{name:selected.name});selected=null;await load()})">Archive paper</button></template><h3 v-if="reviews.length">{{manager?'Submissions & marking':'Your attempt'}}</h3><article v-for="a in reviews" class="paper-question"><p>{{manager?a.student:'Your submission'}} · {{a.status}}</p><a v-if="a.file_id" :href="'/api/method/institute_lms.papers.answer_file?attempt='+encodeURIComponent(a.name)" target="_blank" rel="noopener">View answer PDF</a><template v-if="manager&&a.status!=='Started'"><div v-for="(answer,i) in JSON.parse(a.answers||'[]')" class="paper-answer"><strong>Answer {{i+1}}</strong><p>{{typeof answer==='number'?selected.questions[i]?.options[answer]:answer??'Unanswered'}}</p></div><label>Total mark<input v-model.number="a.score" type="number" min="0" :max="selected.max_marks"></label><label>Feedback<textarea v-model="a.feedback" maxlength="2000"></textarea></label><button class="button primary" :disabled="busy" @click="mark(a)">Save marks</button></template><template v-else><p v-if="a.status==='Graded'">{{a.score}} / {{selected.max_marks}}</p><p>{{a.feedback||'Feedback will appear after marking.'}}</p><button v-if="a.status==='Started'&&!attempt" class="button subtle" @click="begin">Resume attempt</button></template></article></section><div class="paper-actions"><button class="button subtle" :disabled="page===0||busy" @click="page--;run(load)">Previous</button><button class="button subtle" :disabled="rows.length<30||busy" @click="page++;run(load)">Next</button></div></template></section></template>
<style>.paper-panel{padding:28px;margin:20px 0}.paper-panel h2{margin:16px 0;font-size:23px}.paper-panel p{font-size:13px;line-height:1.8;margin:12px 0}.paper-panel label{display:flex;flex-direction:column;font-size:12px;gap:8px;margin:15px 0}.paper-panel :is(input,select,textarea){padding:12px;border:1px solid var(--student-border,#e5daee);border-radius:10px;color:var(--student-ink,#53425f);background:var(--student-card,#fff);min-width:0}.paper-panel textarea{min-height:90px;width:100%}.paper-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 22px}.paper-panel .paper-check{flex-direction:row;align-items:center;gap:12px}.paper-check input{width:18px;height:18px;accent-color:#9474b5}.paper-question{padding:22px;border:1px solid var(--student-border,#e5daee);border-radius:16px;margin:20px 0}.paper-question legend{font-size:14px;padding:8px;line-height:1.7}.paper-actions{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin-top:20px}.paper-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.paper-empty{grid-column:1/-1;text-align:center;padding:60px}.paper-tabs{display:flex;gap:10px;margin:25px 0}.paper-tabs button{padding:11px 20px;border:1px solid #e4d8ef;border-radius:12px;color:#82629d;background:none;cursor:pointer}.paper-tabs button.active{background:#efe4f9}.paper-clock{position:sticky;top:15px;border-radius:14px;padding:16px;background:#8e6cac;color:#fff;text-align:center;font-variant-numeric:tabular-nums;font-size:24px;z-index:3}.paper-answer{padding:10px 0;font-size:12px;border-bottom:1px solid #e8dfee}@media(max-width:650px){.paper-fields,.paper-grid{grid-template-columns:1fr}.paper-panel{padding:20px}.paper-space .page-heading{flex-wrap:wrap;gap:20px}}</style>
